/// Data class for a single level's schedule entry.
class LevelScheduleEntry {
  final int levelNumber;
  final String shapeName;
  final String shapeCategory;
  final LevelType levelType;
  final bool isShapePuzzle;

  const LevelScheduleEntry({
    required this.levelNumber,
    required this.shapeName,
    required this.shapeCategory,
    required this.levelType,
    this.isShapePuzzle = false,
  });
}

