    if (levelNumber >= 1 && levelNumber <= 2000) {
      return _schedule[levelNumber - 1];
    }
    // Beyond 2000: wrap around from level 4 onward (skip tutorials)
    final wrapped = ((levelNumber - 4) % 1997) + 4;
    return _schedule[wrapped - 1];
  }

